import {WindowMotion} from './foundation/window-motion.js';
import {StickyNoteWindowOwner} from './foundation/notes/sticky-note-window.js';

const root=document.getElementById('w6a-root');
const viewport=()=>({width:innerWidth,height:innerHeight,topInset:8,rightInset:8,bottomInset:8,leftInset:8});
const hostGraph={},owner=new StickyNoteWindowOwner({hostGraph,viewport});
owner.register('browser-note',{geometry:{x:180,y:150,width:420,height:330},invokerId:'reopenButton'});
const note=document.getElementById('stickyWindow'),invoker=document.getElementById('reopenButton'),scrollport=document.getElementById('noteScroll');
const render=()=>{const w=owner.window('browser-note'),g=w.geometry;Object.assign(note.style,{left:`${g.x}px`,top:`${g.y}px`,width:`${g.width}px`,height:`${g.height}px`,zIndex:String(g.zOrder||w.zOrder)});note.hidden=w.lifecycle!=='open';note.dataset.lifecycle=w.lifecycle;note.dataset.active=String(w.active);document.getElementById('stateOut').textContent=JSON.stringify(w)};
const edgeFor=target=>target.closest?.('[data-edge]')?.dataset.edge||null;
const motion=new WindowMotion(target=>{if(!target.closest?.('#stickyWindow'))return null;const edge=edgeFor(target);if(!edge&&!target.closest?.('[data-drag]'))return null;return owner.motionBinding('browser-note',note,{edge})});
document.addEventListener('pointerdown',event=>motion.down(event));
document.addEventListener('pointermove',event=>{if(motion.move(event))render()});
document.addEventListener('pointerup',event=>{if(motion.up(event))render()});
document.addEventListener('pointercancel',()=>{if(motion.cancel('pointercancel'))render()});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&motion.active){motion.cancel('Escape');render();note.focus();return}if(note.contains(document.activeElement)||document.activeElement===note){const result=owner.keyboardGeometry('browser-note',event);if(result.handled){render();note.focus();}}});
document.getElementById('hideButton').addEventListener('click',()=>{const result=owner.hide('browser-note');render();document.getElementById(result.focusReturnId)?.focus()});
invoker.addEventListener('click',()=>{owner.open('browser-note');render();note.focus()});
window.addEventListener('resize',()=>{owner.reclamp('browser-note',{reason:'browser-resize'});render()});
scrollport.addEventListener('scroll',()=>{root.dataset.scrollTop=String(scrollport.scrollTop)});
render();
globalThis.W6AStickyWindowBrowser={owner,motion,note,invoker,render,overflow:()=>owner.overflowProjection('browser-note',{contentHeight:document.getElementById('longContent').scrollHeight,toolbarHeight:document.getElementById('bottomToolbar').offsetHeight,statusHeight:document.getElementById('bottomStatus').offsetHeight,titleHeight:document.getElementById('titleBar').offsetHeight})};
